------------ define ------------
local GoodNodePrefabPath = "Game.Behaviours.GoodNodeMB"
local QuickTapType     = typeof(CS.HedgehogTeam.EasyTouch.QuickTap)
local QuickLongTapType = typeof(CS.HedgehogTeam.EasyTouch.QuickLongTap)
local ReverseScaleType = typeof(CS.Game.Native.Common.ReverseScale)
--local CanvasGroupType  = typeof(CS.UnityEngine.CanvasGroup)
------------ define ------------

function UICultivateEquipBackpackCellNode:__init()
end

function UICultivateEquipBackpackCellNode:__delete()
    self.tapComp     = nil
    self.longTapComp = nil
    self.clickAction = nil
    self.longTapAction = nil
end

function UICultivateEquipBackpackCellNode:Awake()

    local gameObject = self.controller.gameObject
    self.tapComp     = KTool.GetComponent(gameObject, QuickTapType)
    self.longTapComp = KTool.GetComponent(gameObject, QuickLongTapType)

    self.reScaleComp = KTool.GetComponent(self.GoodNode.gameObject, ReverseScaleType)

    self.tapComp.onTap:AddListener(Bind(self, self.OnNodeClickAction))
    self.longTapComp.onLongTap:AddListener(Bind(self, self.OnNodeLongTapAction))
end

function UICultivateEquipBackpackCellNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象 self:Delete()
    self:Delete()
    self = nil
end


