function UICultivateEquipBackpackCellNode:RefreshUI(goodsNodeData, isShowExpUp, isShowLock, index)
    self.index         = index
    self.goodsNodeData = goodsNodeData
    KTool.SetActive(self.GoodNode.gameObject, true)

    self.reScaleComp:ResetScale()

    ---@type GoodNodeMB
    local mbEnv = CfUtils.GetLuaScr(self.GoodNode.gameObject, GoodNodePrefabPath)
    if mbEnv then
        mbEnv:Reload(goodsNodeData)
        if isShowLock ~= nil then
            mbEnv:RefreshLockedShowState(isShowLock)
        end
    end
end

function UICultivateEquipBackpackCellNode:SetCheckState(isSelect)
    ---@type GoodNodeMB
    local mbEnv = CfUtils.GetLuaScr(self.GoodNode.gameObject, GoodNodePrefabPath)
    if mbEnv then
        mbEnv:SetCheckState(isSelect)
    end
end

function UICultivateEquipBackpackCellNode:SetEquipOrCoreSpecificState(dojo, cardCareerId)
    ---@type GoodNodeMB
    local mbEnv = CfUtils.GetLuaScr(self.GoodNode.gameObject, GoodNodePrefabPath)
    if mbEnv then
        mbEnv:SetEquipOrCoreSpecificState(dojo, cardCareerId)
    end
end

function UICultivateEquipBackpackCellNode:RefreshLockedShowState(isShowLock)
    ---@type GoodNodeMB
    local mbEnv = CfUtils.GetLuaScr(self.GoodNode.gameObject, GoodNodePrefabPath)
    if mbEnv then
        mbEnv:RefreshLockedShowState(isShowLock)
    end
end


