function UICultivateEquipBackpackCellNode:OnNodeClickAction()
    if self.clickAction then
        self.clickAction({selectedObject = self.controller.gameObject, goodsNodeData = self.goodsNodeData, index = self.index})
    end
end

function UICultivateEquipBackpackCellNode:OnNodeLongTapAction()
    if self.longTapAction then
        self.longTapAction({selectedObject = self.controller.gameObject, goodsNodeData = self.goodsNodeData, index = self.index})
    end
end

